		*val = runtime_to_empty_mins_raw;
		break;
	case BQ27Z746_CMD_RUNTIME_TO_FULL:
		*val = runtime_to_full_mins_raw;
		break;
	case BQ27Z746_CMD_MFR_ACCESS:
		*val = sbs_mfr_access_word_raw;
		break;
	case BQ27Z746_CMD_RELATIVE_STATE_OF_CHARGE:
