	case BQ27Z746_CMD_VOLTAGE:
		*val = voltage_uv_raw;
		break;
	case BQ27Z746_CMD_AT_RATE:
		*val = sbs_at_rate_raw;
		break;
	case BQ27Z746_CMD_CHARGE_VOLTAGE:
		*val = chg_voltage_uv_raw;
		break;
	case BQ27Z746_CMD_CHARGE_CURRENT:
		*val = chg_current_ua_raw;
		break;
