static int bq27z746_emul_transfer_i2c(const struct emul *target, struct i2c_msg *msgs,
				      int num_msgs, int addr)
{
	struct bq27z746_emul_data *data = target->data;
	const struct bq27z746_emul_cfg *cfg = target->cfg;
	int ret = 0;

	if (cfg->addr != addr) {
		LOG_ERR("Address mismatch, expected %02x, got %02x", cfg->addr, addr);
		return -EIO;
	}

	i2c_dump_msgs_rw(target->dev, msgs, num_msgs, addr, false);

	if (num_msgs == 0) {
		return -EIO;
	}

	/* First message is always a write to set the command/register */
	if (msgs[0].flags & I2C_MSG_READ) {
		LOG_ERR("Unexpected read as first message");
		return -EIO;
	}

	if (msgs[0].len == 0) {
		/* Zero-length write used for I2C device probing - ACK it */
		return 0;
	}

	data->cur_cmd = msgs[0].buf[0];

	if (num_msgs == 1) {
		/* Single message: write command and potentially data */
		if (msgs[0].len > 1) {
			/* This would be a write to a command with data.
			 * For this emulator, we only need to handle reads for now.
			 * If the test adds write scenarios, this needs to be extended.
			 */
			LOG_WRN("Write with data to command 0x%x not implemented", data->cur_cmd);
		}
		return 0;
	}

	/* Two messages: write command, then read data */
	if (num_msgs == 2) {
		if (!(msgs[1].flags & I2C_MSG_READ)) {
			LOG_ERR("Expected read as second message");
			return -EIO;
		}

		/* Handle buffer reads (Manufacturer Name, Device Name, Device Chemistry) */
		if (data->cur_cmd == BQ27Z746_CMD_MANUFACTURER_NAME) {
			size_t str_len = sizeof(mfg_name_str) - 1;
			size_t copy_len = MIN(msgs[1].len - 1, str_len); /* -1 for length byte */
			if (msgs[1].len == 0) {
				LOG_ERR("Read buffer too small for length byte");
				return -EIO;
			}
			msgs[1].buf[0] = str_len; /* First byte is length */
			if (copy_len > 0) {
				memcpy(&msgs[1].buf[1], mfg_name_str, copy_len);
			}
			return 0;
		} else if (data->cur_cmd == BQ27Z746_CMD_DEVICE_NAME) {
			size_t str_len = sizeof(dev_name_str) - 1;
			size_t copy_len = MIN(msgs[1].len - 1, str_len);
			if (msgs[1].len == 0) {
				LOG_ERR("Read buffer too small for length byte");
				return -EIO;
			}
			msgs[1].buf[0] = str_len;
			if (copy_len > 0) {
				memcpy(&msgs[1].buf[1], dev_name_str, copy_len);
			}
			return 0;
		} else if (data->cur_cmd == BQ27Z746_CMD_DEVICE_CHEMISTRY) {
			size_t str_len = sizeof(dev_chem_str) - 1;
			size_t copy_len = MIN(msgs[1].len - 1, str_len);
			if (msgs[1].len == 0) {
				LOG_ERR("Read buffer too small for length byte");
				return -EIO;
			}
			msgs[1].buf[0] = str_len;
			if (copy_len > 0) {
				memcpy(&msgs[1].buf[1], dev_chem_str, copy_len);
			}
			return 0;
		}

		/* Handle 2-byte register reads */
		if (msgs[1].len != 2) {
			LOG_ERR("Expected 2 bytes for command 0x%x, got %d", data->cur_cmd,
				msgs[1].len);
			return -EIO;
		}

		uint16_t val;
		ret = emul_bq27z746_reg_read(target, data->cur_cmd, &val);
		if (ret) {
			return ret;
		}
		sys_put_be16(val, msgs[1].buf); /* BQ27Z746 uses big-endian */
		return 0;
	}

	LOG_ERR("Invalid number of messages: %d", num_msgs);
	return -EIO;
}

static const struct i2c_emul_api bq27z746_emul_api_i2c = {
	.transfer = bq27z746_emul_transfer_i2c,
