static int bq27z746_emul_transfer_i2c(const struct emul *target, struct i2c_msg *msgs,
				       int num_msgs, int addr)
{
	struct bq27z746_emul_data *data = target->data;
	unsigned int val;
	uint16_t value;
	int reg;
	int rc = 0;

	__ASSERT_NO_MSG(msgs && num_msgs);

	i2c_dump_msgs_rw(target->dev, msgs, num_msgs, addr, false);

	if (num_msgs == 1) {
		if (msgs->flags & I2C_MSG_READ) {
			LOG_ERR("Unexpected single-message read");
			return -EIO;
		}
		if (msgs->len != 1) {
			LOG_ERR("Unexpected msg0 length %d", msgs->len);
			return -EIO;
		}
		reg = msgs->buf[0];
		// This is a single byte write, likely setting the register pointer for a subsequent read.
		// No need to store in data->cur_reg as the next message will have the register.
		return 0;
	} else if (num_msgs == 2) {
		if (msgs[0].flags & I2C_MSG_READ) {
			LOG_ERR("Unexpected read in first message");
			return -EIO;
		}
		if (msgs[0].len != 1) {
			LOG_ERR("Unexpected msg0 length %d", msgs[0].len);
			return -EIO;
		}
		reg = msgs[0].buf[0];

		/* Now process the second message */
		struct i2c_msg *msg1 = &msgs[1];

		if (msg1->flags & I2C_MSG_READ) {
			// This is a read operation
			if (reg == 0x03) { // ManufacturerName (Block Read)
				const char *mfg_name = "Texas Instruments";
				uint8_t len = strlen(mfg_name);
				if (msg1->len < len + 1) { // +1 for length byte
					LOG_ERR("Buffer too small for ManufacturerName");
					return -ENOMEM;
				}
