				memcpy(&msg1->buf[1], mfg_name, len);
				rc = 0;
			} else if (reg == 0x04) { // DeviceName (Block Read) or StateOfHealth (Word Read)
				if (msg1->len > 2) { // Assume block read for DeviceName
					const char *dev_name = "BQ27Z746";
					uint8_t len = strlen(dev_name);
					if (msg1->len < len + 1) {
						LOG_ERR("Buffer too small for DeviceName");
						return -ENOMEM;
					}
					msg1->buf[0] = len;
					memcpy(&msg1->buf[1], dev_name, len);
					rc = 0;
				} else if (msg1->len == 2) { // Assume word read for StateOfHealth
					rc = emul_bq27z746_reg_read(target, reg, &val);
					if (rc) {
