				} else {
					LOG_ERR("Unexpected msg1 length %d for reg 0x%x", msg1->len, reg);
					return -EIO;
				}
			} else if (reg == 0x05) { // DeviceChemistry (Block Read)
				const char *dev_chem = "LION";
				uint8_t len = strlen(dev_chem);
				if (msg1->len < len + 1) {
					LOG_ERR("Buffer too small for DeviceChemistry");
					return -ENOMEM;
				}
				msg1->buf[0] = len;
				memcpy(&msg1->buf[1], dev_chem, len);
				rc = 0;
			} else {
				// Assume 2-byte word read for other registers
				if (msg1->len != 2) {
					LOG_ERR("Unexpected msg1 length %d for reg 0x%x", msg1->len, reg);
					return -EIO;
				}
				rc = emul_bq27z746_reg_read(target, reg, &val);
				if (rc) {
					return rc;
				}
				sys_put_le16(val, msg1->buf);
			}
		} else {
			// This is a write operation (reg + 2 bytes)
			if (msg1->len != 2) {
				LOG_ERR("Unexpected msg1 length %d for write", msg1->len);
				return -EIO;
			}
			value = sys_get_le16(msg1->buf);
			rc = emul_bq27z746_reg_write(target, reg, value);
		}
	} else {
		LOG_ERR("Invalid number of messages: %d", num_msgs);
		return -EIO;
	}

	return rc;
}

